export function generateAlienTexture(type: number, frame: number = 0): THREE.CanvasTexture {
    const pattern = PATTERNS[type];
    if (!pattern) {
        return createBlankTexture();
    }

    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 16;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = 'transparent';
    ctx.fillRect(0, 0, 16, 16);

    const pixels = pattern.pixels.slice();

    // Animation frame: shift bottom row for "walking" effect
    if (frame === 1) {
        const lastRow = pixels.splice(pixels.length - 16);
        pixels.unshift(...lastRow);
    }

    const color = ALIEN_COLORS[type];
    ctx.fillStyle = color;

    for (let y = 0; y < 16; y++) {
        for (let x = 0; x < 16; x++) {
            if (pixels[y * 16 + x]) {
                ctx.fillRect(x, y, 1, 1);
            }
        }
    }

    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
}

export function generatePlayerTexture(): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 16;
    const ctx = canvas.getContext('2d')!;

    // Player ship shape - wedge/saucer design
    ctx.fillStyle = '#00ffff';
    ctx.beginPath();
    ctx.moveTo(16, 0);
    ctx.lineTo(32, 16);
    ctx.lineTo(28, 16);
    ctx.lineTo(24, 10);
    ctx.lineTo(8, 10);
    ctx.lineTo(4, 16);
    ctx.lineTo(0, 16);
    ctx.closePath();
    ctx.fill();

    // Engine glow detail
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(15, 12, 2, 3);

    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
}

export function generateProjectileTexture(isPlayer: boolean): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 4;
    canvas.height = 8;
    const ctx = canvas.getContext('2d')!;

    if (isPlayer) {
        ctx.fillStyle = '#00ffff';
        ctx.fillRect(1, 0, 2, 8);
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(1, 2, 2, 4);
    } else {
        ctx.fillStyle = '#ff3366';
        ctx.fillRect(1, 0, 2, 8);
        ctx.fillStyle = '#ff9966';
        ctx.fillRect(1, 2, 2, 4);
    }

    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
}

export function generateShieldBlockTexture(): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 8;
    canvas.height = 8;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = '#00ff88';
    ctx.fillRect(0, 0, 8, 8);
    ctx.fillStyle = '#00cc66';
    ctx.fillRect(1, 1, 6, 6);
    ctx.fillStyle = '#00ff88';
    ctx.fillRect(2, 2, 4, 4);

    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
}

export function generateStarfieldTexture(): THREE.DataTexture {
    const size = 2048;
    const data = new Uint8Array(size * size * 3);
    for (let i = 0; i < size * size; i++) {
        const brightness = Math.random() > 0.7 ? Math.floor(Math.random() * 255) : 0;
        data[i * 3] = brightness;
        data[i * 3 + 1] = brightness;
        data[i * 3 + 2] = brightness;
    }

    const tex = new THREE.DataTexture(data, size, size);
    tex.needsUpdate = true;
    return tex;
}

function createBlankTexture(): THREE.CanvasTexture {
    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 16;
    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = '#ff00ff';
    ctx.fillRect(0, 0, 16, 16);

    const tex = new THREE.CanvasTexture(canvas);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
}

import * as THREE from 'three';
import { TextureGenerator } from '../assets/TextureGenerator.js';

export interface AlienData {
    mesh: THREE.Mesh;
    type: number;
    row: number;
    col: number;
    alive: boolean;
    frame: number;
}

const ALIEN_COLORS = [0x00ffff, 0xff00ff, 0xffff00, 0x00ff88, 0xff3366];
const ALIEN_EMISSIVE_COLORS = [0x004444, 0x440044, 0x444400, 0x004422, 0x441122];

export class Alien implements AlienData {
    mesh: THREE.Mesh;
    type: number;
    row: number;
    col: number;
    alive: boolean = true;
    frame: number = 0;

    private _targetPos: THREE.Vector3 | null = null;
    private _morphStart: THREE.Vector3 | null = null;
    private _morphProgress: number = 1.0;
    private readonly MORPH_DURATION = 0.3;

    constructor(type: number, row: number, col: number) {
        this.type = type;
        this.row = row;
        this.col = col;
        this.frame = 0;

        const texture = TextureGenerator.generateAlienTexture(type, 0);
        const geo = new THREE.BoxGeometry(1.2, 0.8, 0.4);
        const mat = new THREE.MeshStandardMaterial({
            map: texture,
            emissive: ALIEN_EMISSIVE_COLORS[type],
            emissiveIntensity: 0.5,
            color: ALIEN_COLORS[type],
        });

        this.mesh = new THREE.Mesh(geo, mat);
        this.mesh.position.set(0, 0, 0);
        texture.dispose();
    }

    setInitialPosition(pos: THREE.Vector3): void {
        this.mesh.position.copy(pos);
        this._targetPos = null;
        this._morphStart = null;
        this._morphProgress = 1.0;
    }

    morphTo(newPos: THREE.Vector3, duration?: number): void {
        if (this._morphProgress >= 1.0) {
            this._morphStart = new THREE.Vector3().copy(this.mesh.position);
            this._targetPos = newPos.clone();
            this._morphProgress = 0;
        }
    }

    updateMorph(delta: number): void {
        if (this._morphStart && this._targetPos && this._morphProgress < 1.0) {
            const dur = duration ?? this.MORPH_DURATION;
            this._morphProgress += delta / dur;
            if (this._morphProgress >= 1.0) {
                this.mesh.position.copy(this._targetPos);
                this._morphStart = null;
                this._targetPos = null;
                this._morphProgress = 1.0;
            } else {
                const t = easeInOutQuad(this._morphProgress);
                this.mesh.position.lerpVectors(this._morphStart, this._targetPos, t);
            }
        }
    }

    toggleFrame(): void {
        this.frame = this.frame === 0 ? 1 : 0;
        const texture = TextureGenerator.generateAlienTexture(this.type, this.frame);
        if (this.mesh.material instanceof THREE.MeshStandardMaterial) {
            if (this.mesh.material.map) this.mesh.material.map.dispose();
            this.mesh.material.map = texture;
            this.mesh.material.needsUpdate = true;
        }
    }

    dispose(): void {
        if (this.mesh.geometry) this.mesh.geometry.dispose();
        if (this.mesh.material instanceof THREE.MeshStandardMaterial) {
            if (this.mesh.material.map) this.mesh.material.map.dispose();
            this.mesh.material.dispose();
        }
        this.mesh.parent?.remove(this.mesh);
    }
}

function easeInOutQuad(t: number): number {
    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

import * as THREE from 'three';

export interface FloatingScoreData {
    sprite: THREE.Sprite;
    startTime: number;
    lifetime: number;
}

let sprites: FloatingScoreData[] = [];

export function initFloatingScoreText(): void {
    sprites = [];
}

export function disposeFloatingScoreText(): void {
    for (const s of sprites) {
        if (s.sprite.material instanceof THREE.SpriteMaterial) {
            s.sprite.material.dispose();
        }
        s.sprite.geometry?.dispose();
    }
    sprites = [];
}

export function spawn(
    engine: { scene: THREE.Scene; clock: THREE.Clock },
    position: THREE.Vector3,
    text: string,
    color: string,
    lifetimeMs: number = 1000
): void {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 128;
    const ctx = canvas.getContext('2d')!;

    ctx.clearRect(0, 0, 256, 128);
    ctx.font = 'bold 72px "Courier New", monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Glow effect
    ctx.shadowColor = color;
    ctx.shadowBlur = 20;
    ctx.fillStyle = color;
    ctx.fillText(text, 128, 64);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.LinearFilter;
    const material = new THREE.SpriteMaterial({ map: texture, transparent: true, opacity: 1.0 });
    const sprite = new THREE.Sprite(material);

    sprite.position.copy(position);
    sprite.position.y += 1.5;
    sprite.scale.set(2.0, 1.0, 1.0);

    engine.scene.add(sprite);

    sprites.push({ sprite, startTime: engine.clock.getElapsedTime(), lifetime: lifetimeMs / 1000 });
}

export function update(engine: { clock: THREE.Clock; scene: THREE.Scene }): void {
    const now = engine.clock.getElapsedTime();
    const toRemove: FloatingScoreData[] = [];

    for (const entry of sprites) {
        const elapsed = now - entry.startTime;
        const t = Math.min(elapsed / entry.lifetime, 1.0);

        // Fade out over lifetime
        if (entry.sprite.material instanceof THREE.SpriteMaterial) {
            entry.sprite.material.opacity = 1.0 - t;
        }

        // Float upward
        entry.sprite.position.y += 0.8 * engine.clock.getDelta?.() ?? 0.016;

        // Scale pulse at start then shrink
        const scalePulse = 1.0 + Math.sin(t * Math.PI) * 0.3;
        entry.sprite.scale.set(2.0 * scalePulse, 1.0 * scalePulse, 1.0);

        if (t >= 1.0) {
            toRemove.push(entry);
        }
    }

    for (const entry of toRemove) {
        const idx = sprites.indexOf(entry);
        if (idx !== -1) {
            sprites.splice(idx, 1);
            if (entry.sprite.material instanceof THREE.SpriteMaterial) {
                entry.sprite.material.dispose();
            }
            entry.sprite.geometry?.dispose();
            engine.scene.remove(entry.sprite);
        }
    }
}

