export class ProjectilePool extends ObjectPool<Projectile> {
    constructor(maxCount: number) {
        super(maxCount, () => new Projectile());
    }

    acquire(position: THREE.Vector3, owner: 'player' | 'alien', vx: number = 0, vy: number): Projectile {
        const projectile = this.get();
        projectile.init(position);
        projectile.owner = owner;
        projectile.setVelocity(vx, vy);
        return projectile;
    }

    release(projectile: Projectile): void {
        projectile.setActive(false);
        this.put(projectile);
    }

    getAll(): Projectile[] {
        const result: Projectile[] = [];
        for (let i = 0; i < this.pool.length; i++) {
            const p = this.pool[i];
            if (p.isActive()) {
                result.push(p);
            }
        }
        return result;
    }

    dispose(): void {
        for (const projectile of this.pool) {
            projectile.dispose();
        }
        super.dispose();
    }
}

import { ObjectPool } from '@shared/ObjectPool';
import { ProjectileData, ProjectileEntity } from '../entities/Projectile.js';

export class ProjectilePool extends ObjectPool<ProjectileData, ProjectileEntity> {
    private _playerProjectiles: ProjectileEntity[] = [];
    private _alienProjectiles: ProjectileEntity[] = [];

    constructor(maxCount: number) {
        super(maxCount);
    }

    protected createObject(): ProjectileEntity {
        const p = new ProjectileEntity();
        this._pool.push(p);
        return p;
    }

    acquirePlayer(position: THREE.Vector3): ProjectileEntity | null {
        if (this._playerProjectiles.length === 0) {
            const obj = this.acquire();
            if (!obj) return null;
            obj.resetForPlayer(position);
            this._playerProjectiles.push(obj);
            return obj;
        }
        const p = this._playerProjectiles.pop()!;
        p.resetForPlayer(position);
        return p;
    }

    acquireAlien(position: THREE.Vector3): ProjectileEntity | null {
        if (this._alienProjectiles.length === 0) {
            const obj = this.acquire();
            if (!obj) return null;
            obj.resetForAlien(position);
            this._alienProjectiles.push(obj);
            return obj;
        }
        const p = this._alienProjectiles.pop()!;
        p.resetForAlien(position);
        return p;
    }

    releaseProjectile(p: ProjectileEntity): void {
        if (this._playerProjectiles.includes(p)) {
            p.dispose();
            this.release(this._playerProjectiles.splice(this._playerProjectiles.indexOf(p), 1)[0]);
        } else if (this._alienProjectiles.includes(p)) {
            p.dispose();
            this.release(this._alienProjectiles.splice(this._alienProjectiles.indexOf(p), 1)[0]);
        }
    }

    getAllActive(): ProjectileEntity[] {
        return [...this._playerProjectiles, ...this._alienProjectiles];
    }

    disposeAll(): void {
        for (const p of this._playerProjectiles) {
            p.dispose();
        }
        this._playerProjectiles.length = 0;
        for (const p of this._alienProjectiles) {
            p.dispose();
        }
        this._alienProjectiles.length = 0;
    }
}

import * as THREE from 'three';
import { ObjectPool } from '@shared/ObjectPool';
import { Projectile } from '../entities/Projectile.js';

export class ProjectilePool extends ObjectPool<Projectile> {
    private _activeProjectiles: Projectile[] = [];

    constructor(maxCount: number) {
        super(maxCount, () => new Projectile());
    }

    acquirePlayer(position: THREE.Vector3): Projectile | null {
        const proj = this.get();
        if (!proj) return null;
        proj.initForPlayer(position);
        this._activeProjectiles.push(proj);
        return proj;
    }

    acquireAlien(position: THREE.Vector3): Projectile | null {
        const proj = this.get();
        if (!proj) return null;
        proj.initForAlien(position);
        this._activeProjectiles.push(proj);
        return proj;
    }

    releaseProjectile(proj: Projectile): void {
        const idx = this._activeProjectiles.indexOf(proj);
        if (idx !== -1) {
            this._activeProjectiles.splice(idx, 1);
        }
        proj.reset();
        this.put(proj);
    }

    getAllActive(): Projectile[] {
        return [...this._activeProjectiles];
    }

    updateAll(delta: number, now: number): void {
        const toRemove: Projectile[] = [];
        for (const proj of this._activeProjectiles) {
            proj.update(delta, now);
            if (!proj.isActive()) {
                toRemove.push(proj);
            }
        }
        for (const proj of toRemove) {
            this.releaseProjectile(proj);
        }
    }

    disposeAll(): void {
        for (const proj of this._activeProjectiles) {
            proj.dispose();
        }
        this._activeProjectiles.length = 0;
        super.dispose();
    }
}

