import * as THREE from 'three';

export interface HitStopConfig {
    defaultFreezeMs: number;
    maxFreezeMs: number;
}

const DEFAULT_CONFIG: HitStopConfig = {
    defaultFreezeMs: 60,
    maxFreezeMs: 200,
};

let config: HitStopConfig = { ...DEFAULT_CONFIG };

export function configureHitStop(cfg: Partial<HitStopConfig>): void {
    if (cfg.defaultFreezeMs !== undefined) config.defaultFreezeMs = cfg.defaultFreezeMs;
    if (cfg.maxFreezeMs !== undefined) config.maxFreezeMs = cfg.maxFreezeMs;
}

export function getDefaultFreezeMs(): number { return config.defaultFreezeMs; }
export function getMaxFreezeMs(): number { return config.maxFreezeMs; }

let _instance: HitStopManager | null = null;

export class HitStopManager {
    private active: boolean = false;
    private remainingMs: number = 0;
    private elapsedMs: number = 0;

    constructor() {
        if (_instance) throw new Error('HitStopManager is a singleton');
        _instance = this;
    }

    static getDefault(): HitStopManager {
        return _instance!;
    }

    requestFreeze(durationMs: number): void {
        const capped = Math.min(durationMs, config.maxFreezeMs);
        if (!this.active || capped > this.remainingMs) {
            this.active = true;
            this.remainingMs = capped;
            this.elapsedMs = 0;
        }
    }

    update(deltaMs: number): void {
        if (!this.active) return;
        this.elapsedMs += deltaMs;
        if (this.elapsedMs >= this.remainingMs) {
            this.active = false;
            this.elapsedMs = 0;
            this.remainingMs = 0;
        }
    }

    isActive(): boolean { return this.active; }
    getRemainingMs(): number { return Math.max(0, this.remainingMs - this.elapsedMs); }
}

import * as THREE from 'three';

export interface CameraShakeConfig {
    intensity: number;
    duration: number;
    frequency: number;
}

export class CameraShake {
    private shakeQueue: Array<{
        intensity: number;
        remainingTime: number;
        frequency: number;
        elapsed: number;
    }> = [];
    private currentOffset = new THREE.Vector3();
    private lastTime = 0;

    get offset(): THREE.Vector3 { return this.currentOffset; }

    addTrauma(intensity: number, duration: number, frequency: number = 12): void {
        this.shakeQueue.push({
            intensity,
            remainingTime: duration,
            frequency,
            elapsed: 0,
        });
    }

    update(deltaTime: number, camera: THREE.Camera): void {
        if (this.shakeQueue.length === 0) {
            this.currentOffset.set(0, 0, 0);
            return;
        }

        const dt = Math.min(deltaTime, 0.1);
        let activeShake = false;

        for (let i = this.shakeQueue.length - 1; i >= 0; i--) {
            const shake = this.shakeQueue[i];
            shake.elapsed += dt;
            shake.remainingTime -= dt;

            if (shake.remainingTime <= 0) {
                this.shakeQueue.splice(i, 1);
                continue;
            }

            activeShake = true;
            const t = shake.elapsed * shake.frequency * Math.PI * 2;
            const decayedIntensity = shake.intensity * Math.pow(0.95, shake.elapsed * 60);

            this.currentOffset.x += Math.sin(t) * decayedIntensity * dt * 10;
            this.currentOffset.y += Math.cos(t * 1.3) * decayedIntensity * dt * 5;

            if (shake.intensity > 0.2) {
                this.currentOffset.z += Math.sin(t * 0.7) * decayedIntensity * dt * 2;
            }
        }

        camera.position.add(this.currentOffset);
        this.currentOffset.multiplyScalar(0.9);
    }

    reset(): void {
        this.shakeQueue = [];
        this.currentOffset.set(0, 0, 0);
    }
}

import * as THREE from 'three';

export interface ShockwaveRingData {
    mesh: THREE.Mesh;
    born: number;
    lifetime: number;
    maxRadius: number;
}

const RING_GEOMETRY = new THREE.TorusGeometry(1, 0.06, 8, 48);
const ringInstances: ShockwaveRingData[] = [];
let nextIndex = 0;

export function spawnShockwave(
    position: THREE.Vector3,
    color: number,
    maxRadius: number = 2.0,
    lifetime: number = 0.4,
): void {
    const mat = new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 1.0,
        side: THREE.DoubleSide,
        depthWrite: false,
    });

    const mesh = new THREE.Mesh(RING_GEOMETRY.clone(), mat);
    mesh.position.copy(position);
    mesh.rotation.x = -Math.PI / 2;
    mesh.scale.set(0.01, 0.01, 0.01);

    ringInstances.push({ mesh, born: performance.now(), lifetime, maxRadius });
}

export function update(now: number): void {
    for (let i = ringInstances.length - 1; i >= 0; i--) {
        const r = ringInstances[i];
        const elapsed = (now - r.born) / 1000;
        if (elapsed >= r.lifetime) {
            r.mesh.material.dispose();
            r.mesh.geometry.dispose();
            r.mesh.parent?.remove(r.mesh);
            ringInstances.splice(i, 1);
            continue;
        }

        const t = elapsed / r.lifetime;
        const radius = r.maxRadius * easeOutQuad(t);
        r.mesh.scale.set(radius, radius, radius);
        (r.mesh.material as THREE.MeshBasicMaterial).opacity = 1.0 - t;
    }
}

export function disposeAll(): void {
    for (const r of ringInstances) {
        r.mesh.material.dispose();
        r.mesh.geometry.dispose();
        if (r.mesh.parent) r.mesh.parent.remove(r.mesh);
    }
    ringInstances.length = 0;
}

function easeOutQuad(t: number): number {
    return 1 - (1 - t) * (1 - t);
}

import * as THREE from 'three';
import { CameraShake } from '../../../shared/vfx/CameraShake';
import { HitStopManager, configureHitStop } from '../../../shared/vfx/HitStop';
import { spawnShockwave, update as updateShockwaves, disposeAll as disposeShockwaves } from '../../../shared/vfx/ShockwaveRings';
import { FloatingScoreText } from '../../../shared/vfx/FloatingScoreText';
import { ParticleBursts } from '../../../shared/vfx/ParticleBursts';

const ALIEN_COLORS = [0x00ffff, 0xff00ff, 0xffff00, 0x00ff88, 0xff3366];
const SCORE_LABELS = ['+50', '+40', '+40', '+30', '+20'];

export class SpaceInvadersVFX {
    private cameraShake: CameraShake;
    private hitStopManager: HitStopManager;
    private particleBursts: ParticleBursts;

    constructor() {
        this.cameraShake = new CameraShake();
        this.hitStopManager = new HitStopManager();
        configureHitStop({ defaultFreezeMs: 60, maxFreezeMs: 200 });
        this.particleBursts = new ParticleBursts();

        FloatingScoreText.init();
    }

    getShake(): CameraShake { return this.cameraShake; }
    getHitStop(): HitStopManager { return this.hitStopManager; }

    onAlienKill(row: number, position: THREE.Vector3): void {
        const color = ALIEN_COLORS[row] ?? 0xffffff;
        const label = SCORE_LABELS[row] ?? '+20';

        this.hitStopManager.requestFreeze(60);
        this.particleBursts.spawnBurst(position.clone(), 18, color, 3.0, 0.9);
        spawnShockwave(position.clone(), color, 1.5, 0.4);
        FloatingScoreText.show(position.clone(), label, color, 1.0);
    }

    onPlayerDeath(): void {
        this.cameraShake.addTrauma(0.35, 0.6, 12);
        this.hitStopManager.requestFreeze(150);
        const deathPos = new THREE.Vector3(0, -4, 0);
        this.particleBursts.spawnBurst(deathPos.clone(), 40, 0x00ffff, 5.0, 1.2);
        spawnShockwave(deathPos.clone(), 0x00ffff, 3.0, 0.6);
    }

    onShieldHit(position: THREE.Vector3): void {
        this.particleBursts.spawnBurst(position.clone(), 5, 0x22cc88, 1.5, 0.4);
    }

    updateShake(deltaTime: number, camera: THREE.Camera): void {
        this.cameraShake.update(deltaTime, camera);
    }

    updateHitStop(deltaMs: number): void {
        this.hitStopManager.update(deltaMs);
    }

    isFrozen(): boolean {
        return this.hitStopManager.isActive();
    }

    getFreezeScale(): number {
        if (!this.isFrozen()) return 1.0;
        const remaining = this.hitStopManager.getRemainingMs();
        const total = this.hitStopManager.getRemainingMs() + (60 - remaining);
        // Full freeze when active, slow-mo at end
        if (remaining > 0) {
            return 0.0;
        }
        return 1.0;
    }

    updateShockwaves(now: number): void {
        updateShockwaves(now);
    }

    dispose(): void {
        this.particleBursts.dispose();
        disposeShockwaves();
        FloatingScoreText.dispose();
    }
}

import * as THREE from 'three';

export interface FloatingScoreData {
    sprite: THREE.Sprite;
    startTime: number;
    lifetime: number;
}

let sprites: FloatingScoreData[] = [];

export function initFloatingScoreText(): void {
    sprites = [];
}

export function disposeFloatingScoreText(): void {
    for (const s of sprites) {
        if (s.sprite.material instanceof THREE.SpriteMaterial) {
            s.sprite.material.dispose();
        }
        s.sprite.geometry?.dispose();
    }
    sprites = [];
}

export function spawn(
    engine: { scene: THREE.Scene; clock: THREE.Clock },
    position: THREE.Vector3,
    text: string,
    color: string,
    lifetimeMs: number = 1000
): void {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 128;
    const ctx = canvas.getContext('2d')!;

    ctx.clearRect(0, 0, 256, 128);
    ctx.font = 'bold 72px "Courier New", monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Glow effect
    ctx.shadowColor = color;
    ctx.shadowBlur = 20;
    ctx.fillStyle = color;
    ctx.fillText(text, 128, 64);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.LinearFilter;
    const material = new THREE.SpriteMaterial({ map: texture, transparent: true, opacity: 1.0 });
    const sprite = new THREE.Sprite(material);

    sprite.position.copy(position);
    sprite.position.y += 1.5;
    sprite.scale.set(2.0, 1.0, 1.0);

    engine.scene.add(sprite);

    sprites.push({ sprite, startTime: engine.clock.getElapsedTime(), lifetime: lifetimeMs / 1000 });
}

export function update(engine: { clock: THREE.Clock; scene: THREE.Scene }): void {
    const now = engine.clock.getElapsedTime();
    const toRemove: FloatingScoreData[] = [];

    for (const entry of sprites) {
        const elapsed = now - entry.startTime;
        const t = Math.min(elapsed / entry.lifetime, 1.0);

        // Fade out over lifetime
        if (entry.sprite.material instanceof THREE.SpriteMaterial) {
            entry.sprite.material.opacity = 1.0 - t;
        }

        // Float upward
        const delta = engine.clock.getDelta();
        entry.sprite.position.y += 0.8 * delta;

        // Scale pulse at start then shrink
        const scalePulse = 1.0 + Math.sin(t * Math.PI) * 0.3;
        entry.sprite.scale.set(2.0 * scalePulse, 1.0 * scalePulse, 1.0);

        if (t >= 1.0) {
            toRemove.push(entry);
        }
    }

    for (const entry of toRemove) {
        const idx = sprites.indexOf(entry);
        if (idx !== -1) {
            sprites.splice(idx, 1);
            if (entry.sprite.material instanceof THREE.SpriteMaterial) {
                entry.sprite.material.dispose();
            }
            entry.sprite.geometry?.dispose();
            engine.scene.remove(entry.sprite);
        }
    }
}

